const crypto = require('crypto');

// Extract Razorpay webhook payload
const body = $input.first().json.body;
const headers = $input.first().json.headers || {};
const receivedSignature = headers['x-razorpay-signature'];

console.log('Razorpay Webhook Received:', JSON.stringify(body, null, 2));

// SECURITY: Verify webhook signature
const webhookSecret = 'SubbuInnovative2025';

if (webhookSecret && receivedSignature) {
  try {
    const expectedSignature = crypto
      .createHmac('sha256', webhookSecret)
      .update(JSON.stringify(body))
      .digest('hex');

    if (receivedSignature !== expectedSignature) {
      console.error('⚠️ SECURITY ALERT: Invalid webhook signature detected!');
      throw new Error('Invalid webhook signature - possible fraud attempt');
    }
    console.log('✅ Webhook signature verified');
  } catch (error) {
    console.error('Signature verification failed:', error.message);
    throw error;
  }
} else {
  console.warn('⚠️ WARNING: Webhook signature verification skipped (no secret configured)');
}

// Validate webhook event type
const event = body.event;
if (!event) {
  throw new Error('Invalid webhook: missing event field');
}

// Extract payment data based on event type
let razorpayOrderId, razorpayPaymentId, status;

if (event === 'payment.captured' || event === 'order.paid') {
  const payment = body.payload?.payment || body.payload?.order;

  if (!payment) {
    throw new Error('Invalid webhook: missing payment data');
  }

  razorpayOrderId = payment.order_id;
  razorpayPaymentId = payment.id;
  status = 'paid';

} else if (event === 'payment.failed') {
  const payment = body.payload?.payment;

  if (!payment) {
    throw new Error('Invalid webhook: missing payment data');
  }

  razorpayOrderId = payment.order_id;
  razorpayPaymentId = payment.id;
  status = 'failed';

} else {
  // Unsupported event type - acknowledge but don't process
  return {
    json: {
      success: true,
      message: 'Event acknowledged but not processed: ' + event,
      should_process: false
    }
  };
}

if (!razorpayOrderId) {
  throw new Error('Invalid webhook: missing order_id');
}

console.log('Processed Webhook Data:', {
  event,
  razorpayOrderId,
  razorpayPaymentId,
  status
});

return {
  json: {
    razorpay_order_id: razorpayOrderId,
    razorpay_payment_id: razorpayPaymentId,
    status: status,
    event: event,
    should_process: true,
    raw_payload: body
  }
};

